namespace fault {thread_local long at=-1;thread_local size_t calls=0;}
void *operator new(size_t n){++fault::calls;if(fault::at>=0){if(fault::at==0)throw std::bad_alloc();--fault::at;}if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
